class Solution {
  private static final long MOD = 1_000_000_007L;

  public int maximizeSquareArea(int m, int n, int[] hFences, int[] vFences) {
    int[] h = withBounds(hFences, m), v = withBounds(vFences, n);
    Set<Integer> widths = new HashSet<>();
    for (int i = 0; i < h.length; i++) {
      for (int j = i + 1; j < h.length; j++) widths.add(h[j] - h[i]);
    }
    int best = 0;
    for (int i = 0; i < v.length; i++) {
      for (int j = i + 1; j < v.length; j++) {
        int width = v[j] - v[i];
        if (width > best && widths.contains(width)) best = width;
      }
    }
    return best == 0 ? -1 : (int) ((long) best * best % MOD);
  }

  private int[] withBounds(int[] fences, int bound) {
    int[] result = Arrays.copyOf(fences, fences.length + 2);
    result[fences.length] = 1;
    result[fences.length + 1] = bound;
    Arrays.sort(result);
    return result;
  }
}
